// Writes src/generated/contracts.ts from the repository's contracts and the built-in
// profiles, so the package carries them without reading files at run time (R11).
// Run it after `make schemas` or a profile change: node scripts/sync-contracts.mjs
// A test fails while the generated file differs from what this script would write.

import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..", "..", "..", "..");
const SCHEMAS = ["harness", "profile", "tool-manifest", "eval-dataset"];
const PROFILES = join(ROOT, "python", "harnessweaver", "src", "harnessweaver", "profiles");
export const TARGET = join(HERE, "..", "src", "generated", "contracts.ts");

/** The text the generated module must have. */
export function render() {
  const schemas = Object.fromEntries(
    SCHEMAS.map((name) => [name, JSON.parse(readFileSync(join(ROOT, "contracts", "schemas", `${name}.schema.json`), "utf8"))]),
  );
  const profiles = Object.fromEntries(
    readdirSync(PROFILES)
      .filter((file) => file.endsWith(".yaml"))
      .sort()
      .map((file) => [file.replace(/\.yaml$/, ""), readFileSync(join(PROFILES, file), "utf8")]),
  );
  return [
    "// Generated by scripts/sync-contracts.mjs from contracts/schemas and the built-in",
    "// profiles. Don't edit: run `node scripts/sync-contracts.mjs` instead.",
    "",
    "/** The JSON Schemas the core validates against, by contract name. */",
    `export const SCHEMAS: Record<string, Record<string, unknown>> = ${JSON.stringify(schemas, null, 2)};`,
    "",
    "/** The built-in profiles' YAML text, by name (`profile://<name>`; `defaults` is always first). */",
    `export const PROFILES: Record<string, string> = ${JSON.stringify(profiles, null, 2)};`,
    "",
  ].join("\n");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(TARGET, render(), "utf8");
  console.log(`wrote ${TARGET}`);
}
